/* ---------- order ---------- */
function copyF(label,val){return '<div class="fld"><span class="lbl2">'+label+'</span><div class="inp ro"><input readonly value="'+esc(val)+'" aria-label="'+esc(label)+'"><button class="copy-i" data-act="copy:'+esc(val)+'" aria-label="Скопировать">'+ic('copy',18)+'</button></div></div>'}
function notifyRow(){return '<label class="notify">'+ic('send',22,'#2AABEE')+'<span><b>Уведомления в Telegram</b>Сообщим, когда статус изменится</span><input type="checkbox" class="sw" data-act="notify" '+(S.notify?'checked':'')+' aria-label="Уведомления в Telegram"></label>'}
function waitBlock(t){return '<div class="wait"><span class="spin" aria-hidden="true"></span><span class="purple">'+(t||'Ожидание…')+'</span><span>Закрыть экран можно, мы продолжим обмен</span></div>'+notifyRow()}
function orderRing(labels,cur){var T=labels.length,n=Math.min(cur,T),done=cur>T,c=2*Math.PI*20,nm=labels[n-1],nx=done?'Обмен завершён':'Дальше: '+labels[n];
 return '<div class="stepring in'+(done?' done':'')+'" role="group" aria-label="Этап '+n+' из '+T+'"><div class="ring"><svg width="46" height="46" viewBox="0 0 46 46" aria-hidden="true"><circle cx="23" cy="23" r="20" fill="none" stroke="var(--line)" stroke-width="4"/><circle class="rp" cx="23" cy="23" r="20" fill="none" stroke="'+(done?'var(--ok-ic)':'var(--brand)')+'" stroke-width="4" stroke-linecap="round" stroke-dasharray="'+(c*n/T).toFixed(1)+' '+c.toFixed(1)+'" transform="rotate(-90 23 23)"/></svg><b>'+n+'/'+T+'</b></div><div class="stt"><b>'+nm+'</b><span>'+nx+'</span></div></div>'}
function stepper(labels,cur){return '<div class="stepper" role="list" aria-label="Этапы заявки">'+labels.map(function(l,i){var n=i+1,dn=n<cur,nw=n===cur;return '<div class="stp" role="listitem"><div class="trk"><i class="ln '+(i>0?(n<=cur?'on':''):'off')+'"></i><b class="bul '+(dn?'done':nw?'now':'')+'">'+(dn?ic('checkb',11):n)+'</b><i class="ln '+(i<labels.length-1?(n<cur?'on':''):'off')+'"></i></div><span class="'+(nw?'now':'')+'">'+l+'</span></div>'}).join('')+'</div>'}
