 h+='<div class="sumline"><div class="num">'+amtFmt(o.giveCode,o.give)+' '+short(o.giveCode)+ic('arrow',18)+amtFmt(o.getCode,o.get)+' '+short(o.getCode)+'</div><span>'+esc(cr.name)+' · '+rateStr(cr.code)+' · комиссия включена</span></div>';
 var fl=FLOW[o.dir],ix=fl.indexOf(o.status);
