   if(!o.nameOk){h+='<div class="warnbox">'+ic('warn',18)+'<span>Не совершайте перевод, если имя получателя не соответствует указанному выше.</span></div><div class="ask"><b>Имя получателя соответствует?</b><button class="btn primary" data-act="name:yes">Да</button><button class="btn outline" data-act="name:no">Нет</button></div>'}
