/* типографика: неразрывный пробел после коротких слов, перед тире, между числом и единицей */
var SHORTW='в|во|и|а|к|ко|с|со|у|о|об|обо|от|до|на|по|за|из|не|ни|но|да|для|при|без|над|под|про|или|что|как|это|же|ли|бы|ее|её|их|мы|вы|он|она|они|то|та|те|все|всё|уже|чем|если|чтобы|когда|где|так|там|тут|вас|нас|вам|нам';
var RX_SHORT=new RegExp('(^|[\\s\\u00a0(«"])('+SHORTW+')\\s','gi');
function typo(s){if(!s||s.length<3)return s;
 s=s.replace(RX_SHORT,function(m,a,w){return a+w+' '});s=s.replace(RX_SHORT,function(m,a,w){return a+w+' '});
 s=s.replace(/(\d)[ \u00a0](?=\d{3}(?!\d))/g,'$1\u202f').replace(/(\d)\u202f(?=\d{3}(?!\d))/g,'$1\u202f').replace(/\$\s?(\d)/g,'$$$1').replace(/(\d)\s?\$/g,'$1$$').replace(/(купон|скидк[ау]|скидку)\s/gi,'$1\u00a0');
 s=s.replace(/\s—/g,' —').replace(/(\d)\s(₽|RUB|USDT|USDC|BTC|ETH|TON|мин|ч|сек|%|раз|заяв|минут|дн)/g,'$1 $2').replace(/№\s/g,'№ ');
 return s}
function typoTree(root){if(!root)return;var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:function(n){var p=n.parentNode;if(!p||/^(SCRIPT|STYLE|TEXTAREA|CODE|INPUT)$/.test(p.nodeName)||(p.closest&&p.closest('.num,.amt,.mono,[data-notypo]')))return NodeFilter.FILTER_REJECT;return n.nodeValue.trim().length>2?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}}),n,list=[];while((n=w.nextNode()))list.push(n);list.forEach(function(t){var v=typo(t.nodeValue);if(v!==t.nodeValue)t.nodeValue=v})}
/* иконка рядом с текстом: по верхнему краю текста, при одной строке — по центру */
var IA_SEL='.dbody h3,.dcard,.card.rows .row,.wrow,.why,.notebox,.warnbox,.okbox,.hours .hh,.notify,.check,.eta,.opt,.dsum li,.u,.docnote,.plate,.tg,.timer .row';
var IA_SKIP=['n','ic','wi','wi2','hi','tok','sw','av','mini-copy','seg2','hstat','hst','tag','ptm','bul','dt','bdot','rubmark','ck'];
function textBlockOf(el){var c=el.children;for(var i=0;i<c.length;i++){var x=c[i];if(x.tagName==='svg'||x.tagName==='INPUT')continue;var skip=false;for(var j=0;j<IA_SKIP.length;j++)if(x.classList.contains(IA_SKIP[j])){skip=true;break}if(skip)continue;if(x.textContent.trim())return x}return null}
function alignIcons(root){if(!root)return;[].forEach.call(root.querySelectorAll(IA_SEL),function(el){var t=textBlockOf(el);if(!t)return;var cs=getComputedStyle(t),lh=parseFloat(cs.lineHeight);if(!lh){var f=t.querySelector('b,span,small');lh=f?parseFloat(getComputedStyle(f).lineHeight):20}if(!lh||isNaN(lh))lh=20;var h=t.getBoundingClientRect().height;el.classList.add('ia');el.classList.toggle('one',h<=lh*1.45)})}
/* сумма в калькуляторе не заходит под кнопку смены направления: длинное число уменьшается */
function fitAmts(){[].forEach.call(document.querySelectorAll('#app .crow .amt'),function(a){a.style.fontSize='';var fs=parseFloat(getComputedStyle(a).fontSize),min=17;while(a.scrollWidth>a.clientWidth+0.5&&fs>min){fs-=1;a.style.fontSize=fs+'px'}})}
